fatos.sql:
SELECT COUNT(*) AS pedidos, COUNT(DISTINCT c.customer_unique_id) AS clientes_unicos,
       MIN(CAST(p.order_purchase_timestamp AS DATE)), MAX(CAST(p.order_purchase_timestamp AS DATE))
FROM pedidos p JOIN clientes c ON c.customer_id = p.customer_id;

SELECT COUNT(*) AS clientes_unicos_total,
       SUM(CASE WHEN dia_1 > DATE '2018-10-17' - INTERVAL 90 DAY THEN 1 ELSE 0 END) AS fora_por_censura
FROM primeira_compra_por_cliente;

consultas.sql:
SELECT table_name, column_name, data_type
FROM information_schema.columns
ORDER BY table_name, ordinal_position;

SELECT order_status, count(*) AS n,
       round(100.0*count(*)/sum(count(*)) OVER (),2) AS pct
FROM pedidos GROUP BY 1 ORDER BY n DESC;
